        token = self.tokens.issue(user.id)
        return {"status": "ok", "reset_token": token}

class PasswordResetService:
    def __init__(self, users, tokens, mailer):
        self.users = users
        self.tokens = tokens
        self.mailer = mailer

    def request(self, email):
        user = self.users.find_by_email(email)
        if user is not None:
            token = self.tokens.issue(user.id)
            self.mailer.send_reset(user.email, token)
        return {"message": "if the account exists, an email was sent"}

async def request_reset(email, repo, tokens, sms):
    user = await repo.find_by_email(email)
    if user:
        token = await tokens.issue(user.id)
        await sms.send(user.phone, f"Your code: {token}")
    return {"status": "accepted"}

def request_reset(payload, repo, tokens, mailer):
    user = repo.find_by_email(payload["email"])
    if user:
        token = tokens.issue(user.id)
        mailer.send(user.email, token)
    return {"requested": True, "expires_in": 900}

